(() => {
  const modal = () => {
    if (!window.FileManagerModal) {
      console.warn('[forum-filemanager] FileManagerModal not found');
      return null;
    }
    return window.FileManagerModal;
  };

  const updateHeaderPreview = (imgId, wrapperId, url) => {
    if (!imgId || !wrapperId) return;
    const img = document.getElementById(imgId);
    const wrapper = document.getElementById(wrapperId);
    if (!img || !wrapper) return;
    if (url) {
      img.src = url;
      wrapper.style.display = 'block';
    } else {
      img.src = '';
      wrapper.style.display = 'none';
    }
  };

  const renderPreview = (containerId, url) => {
    const container = document.getElementById(containerId || '');
    if (!container) return;
    if (!url) {
      container.innerHTML = '';
      return;
    }
    container.innerHTML = `<img src="${url}" style="max-width: 100%; height: auto; display: block; border-radius: 4px; margin-top: 8px;">`;
  };

  const bindButtons = () => {
    const buttons = document.querySelectorAll('[data-filemanager-trigger="forum-image"]');
    if (!buttons.length) return;

    buttons.forEach((btn) => {
      btn.addEventListener('click', (event) => {
        event.preventDefault();
        const fm = modal();
        if (!fm) return;

        const targetInputId = btn.dataset.filemanagerTargetInput || '';
        const previewId = btn.dataset.filemanagerPreview || '';
        const headerImgId = btn.dataset.filemanagerHeaderImg || '';
        const headerWrapperId = btn.dataset.filemanagerHeaderWrapper || '';

        fm.open({
          type: btn.dataset.filemanagerType || 'image',
          filetag: 'forum',
          trigger: 'forum-image-button',
          onSelect: (url) => {
            const input = document.getElementById(targetInputId);
            if (input) {
              input.value = url;
            }
            renderPreview(previewId, url);
            updateHeaderPreview(headerImgId, headerWrapperId, url);
          },
        });
      });
    });
  };

  document.addEventListener('DOMContentLoaded', bindButtons);
})();
